import { fmtMoney } from "@/components/ui/primitives";

export type GameTierSummary = {
  id: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
};

/**
 * Game-server "Resize & storage" card.
 *
 * INFORMATIONAL, NOT SELF-SERVICE. A game tier (`GamePlan`) is sold as a fixed,
 * flat-price bundle — `lib/resize.ts` refuses `resizeQuote` outright for any
 * server with a `gamePlanId` ("Game server plans are fixed bundles — switch
 * tiers from the game server's own settings, or contact support"), and
 * `lib/renewal-charge.ts` bills a game plan at ONE flat price with no per-GB
 * disk or backup add-on lines ever added on top ("a game plan is all-in").
 *
 * Wiring the VPS `ResizePicker`/`AddStorage` in here unmodified would either
 * (a) let a customer "resize" onto a raw VPS `Plan` that has nothing to do with
 * what they actually bought, hitting the ResizeError above every time, or
 * (b) let them buy extra disk that is charged once and then rides free on every
 * renewal forever, since `renewalCharge` never re-bills disk for a flat game
 * plan. Neither is a real feature — so this card gives the customer the
 * information those actions can't: what they're on, what else exists, and how
 * to actually move (support does it manually, preserving the world/data).
 */
export function GameTierInfo({
  hostname,
  current,
  otherTiers,
  effectiveDiskGB,
  extraDiskGB,
  supportHref = "/dashboard/support",
}: {
  hostname: string;
  current: GameTierSummary;
  /** Other ACTIVE tiers in the same game family, cheapest first. */
  otherTiers: GameTierSummary[];
  /** plan disk + any extra disk this server holds. */
  effectiveDiskGB: number;
  extraDiskGB: number;
  supportHref?: string;
}) {
  const monthly = Math.round(current.priceCents / Math.max(1, current.termMonths));

  return (
    <div className="card space-y-4">
      <div>
        <h3 className="font-semibold">Resize &amp; storage</h3>
        <p className="mt-1 max-w-xl text-sm text-slate-400">
          Game server tiers are fixed, all-in bundles — CPU, RAM, disk, slots and price move
          together as a set, so they can&apos;t be resized piecemeal the way a VPS plan can.
        </p>
      </div>

      <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-sm font-medium text-slate-200">{current.name}</p>
          <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-brand-300">
            current tier
          </span>
        </div>
        <dl className="mt-3 grid grid-cols-2 gap-x-4 gap-y-1.5 text-xs text-slate-400 sm:grid-cols-4">
          <div>
            <dt className="text-slate-500">CPU</dt>
            <dd className="text-slate-200">{current.cpuCores} vCPU</dd>
          </div>
          <div>
            <dt className="text-slate-500">RAM</dt>
            <dd className="text-slate-200">{(current.ramMB / 1024).toFixed(current.ramMB % 1024 ? 1 : 0)} GB</dd>
          </div>
          <div>
            <dt className="text-slate-500">Disk</dt>
            <dd className="text-slate-200">

"use client";

import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { fmtMoney } from "@/components/ui/primitives";
import { quoteGameTier, changeGameTier } from "@/lib/actions-game-resize";
import type { GameResizeQuote } from "@/lib/game-resize";

/**
 * Self-service tier upgrades, replacing "our team moves you across manually".
 *
 * Only UPGRADES are offered. A smaller tier still routes to support, because
 * the credit side is the direction lib/resize.ts's comment is about — prorating
 * a refund against the wrong plan pays out money the customer never paid.
 *
 * The figure on the confirm step is the server's own quote, not a number this
 * component worked out, so displayed and charged cannot drift.
 */

export type Tier = {
  id: string; name: string; ramMB: number; cpuCores: number;
  diskGB: number; slots: number | null; priceCents: number; termMonths: number;
};

function per(t: Tier): string {
  return t.termMonths === 12 ? "/yr" : t.termMonths > 1 ? `/${t.termMonths}mo` : "/mo";
}

function Spec({ icon, children }: { icon: string; children: React.ReactNode }) {
  return (
    <span className="flex items-center gap-2 text-[12px] text-tx-dim">
      <Icon name={icon} size={12} tone="inherit" className="flex-none text-tx-faint" />
      {children}
    </span>
  );
}

export function TierUpgrade({
  serverId, current, tiers, supportHref, disabled,
}: {
  serverId: string;
  current: Tier;
  /** Other ACTIVE tiers in the same game family. */
  tiers: Tier[];
  supportHref: string;
  disabled: boolean;
}) {
  const [chosen, setChosen] = useState<Tier | null>(null);
  const [quote, setQuote] = useState<GameResizeQuote | null>(null);
  const [quoteErr, setQuoteErr] = useState<string | null>(null);
  const [loadingQuote, setLoadingQuote] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [busy, start] = useTransition();

  const currentMonthly = Math.round(current.priceCents / Math.max(1, current.termMonths));
  const upgrades = tiers.filter((t) => Math.round(t.priceCents / Math.max(1, t.termMonths)) > currentMonthly);
  const smaller = tiers.filter((t) => Math.round(t.priceCents / Math.max(1, t.termMonths)) <= currentMonthly);

  useEffect(() => {
// Game-tier upgrades — the piece lib/resize.ts explicitly refuses.
//
// WHY THIS IS A SEPARATE PATH, not a relaxed guard in resize.ts.
//
// A game server carries BOTH a base `planId` (the VPS Plan that sizes the VM)
// and a `gamePlanId` (the tier the customer actually bought), and is sold at
// `gamePlan.priceCents` — a FLAT, all-in price, typically LOWER than the base
// plan it rides on. The live example in resize.ts's own comment:
// `minecraft-mm8w85` sold at $4.99 on a Starter base plan of $8.99.
//
// Every proration in resize.ts reads `server.plan.priceCents`. Pointing a game
// server at it prices the move against a plan the customer never bought — and
// on the credit side that is real wallet money they never paid, which breaks
// the one invariant lib/proration.ts rests on. So resize.ts refuses, correctly,
// and this module prices against the GAME plan instead, exactly the way
// lib/renewal-charge.ts already does when it renews one.
//
// UPGRADES ONLY, deliberately. The dangerous direction is the credit, and a
// downgrade credit is the thing resize.ts's comment is about. Moving DOWN a
// tier stays a support operation until someone has sat with the round-trip
// maths; nothing here can pay a customer money.
import { db } from "./db";
import { debitWallet } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { prorateUpgradeCents, remainingMonths } from "./proration";
import { annualDiscountPct, frozenAnnualDiscountPct } from "./annual-discount";
import { ResizeError } from "./resize";

/** The per-month rate a game tier bills at. `GamePlan.priceCents` is the price
 *  for the plan's OWN term, so it is divided by that term — the same derivation
