import type { FamilyInstaller } from "../types";
import { minecraftInstaller } from "./minecraft";
import { valheimInstaller } from "./valheim";
import { rustInstaller } from "./rust";
import { cs2Installer } from "./cs2";
import { factorioInstaller } from "./factorio";
import { corekeeperInstaller } from "./corekeeper";

export const ENGINE_INSTALLERS: Record<string, FamilyInstaller> = {
  minecraft: minecraftInstaller,
  valheim: valheimInstaller,
  rust: rustInstaller,
  cs2: cs2Installer,
  factorio: factorioInstaller,
  corekeeper: corekeeperInstaller,
};

export function engineInstallerFor(family: string, source: string): FamilyInstaller | null {
  const i = ENGINE_INSTALLERS[family];
  return i && i.sources.includes(source) ? i : null;
}

export type Coverage =
  | { mode: "engine"; sources: readonly string[]; mechanism: string }
  | { mode: "legacy"; sources: readonly string[]; mechanism: string }
  | { mode: "unavailable"; reason: string };

/** Families with a pre-engine worker path (see worker/game-mods.ts). */
const LEGACY: Record<string, { sources: string[]; mechanism: string }> = {
