export function familyCoverage(family: string): Coverage {
  const e = ENGINE_INSTALLERS[family];
  const off = e?.unavailableReason?.();
  if (e && off) return { mode: "unavailable", reason: off };
  if (e) return { mode: "engine", sources: e.sources, mechanism: e.mechanism };
  const l = LEGACY[family];
  if (l) return { mode: "legacy", sources: l.sources, mechanism: l.mechanism };
  return { mode: "unavailable", reason: UNAVAILABLE[family] ?? "One-click mods aren't available for this game yet. Upload files in Files and restart from Console." };
}

export const COVERAGE_LEGACY = LEGACY;
export const COVERAGE_UNAVAILABLE = UNAVAILABLE;

/**
 * What the customer sees under "Mods & Plugins" for this game. `mechanism` stays
 * internal (env var names, file formats); this is the plain-language version.
 */
export function customerCoverageText(family: string): string {
  const c = familyCoverage(family);
  if (c.mode === "unavailable") return c.reason;
  if (c.sources.includes("steam_workshop")) return "Steam Workshop mods are added to your server's mod list and your server downloads them itself when it restarts.";
  return "Mods load when your server restarts.";
}
